written = 0
for cid in IDS:
    rec = {"case_id": cid, "prediction_text": P[cid]["prediction_text"], "basis": P[cid]["basis"],
           "confidence": P[cid]["confidence"], "trigger": P[cid]["trigger"]}
    with open(os.path.join(BASE, cid + ".json"), "w", encoding="utf-8") as f:
        json.dump(rec, f, ensure_ascii=False, indent=1)
    written += 1

# 自验断言
assert written == len(IDS) == 20
for cid in IDS:
    p = os.path.join(BASE, cid + ".json")
    with open(p, encoding="utf-8") as f:
        d = json.load(f)
    assert d["case_id"] == cid and os.path.basename(p) == cid + ".json"
    for k in ("case_id", "prediction_text", "basis", "confidence", "trigger"):
        assert k in d, (cid, k)
    assert isinstance(d["confidence"], (int, float)) and 0 <= d["confidence"] <= 1
    for b in ("changed_main", "reserve_used", "disputed", "reason"):
        assert b in d["trigger"], (cid, b)
